import React from 'react';

import {
  DrillDownTableHeader,
  DrillDownTableRow,
  DrillDownTableToolbar,
} from './components';
import {
  DDT_SPACING,
  DDTBody,
  DDTCard,
  DDTTable,
} from './DrillDownTable.styles';
import { DrillDownTableProps } from './DrillDownTable.types';

const DEFAULT_AXIS_WIDTH = DDT_SPACING.axisDefaultWidth;
const DEFAULT_AXIS_TITLE = 'Drivers';

export const DrillDownTable: React.FC<DrillDownTableProps> = ({
  title,
  unit,
  columnGroups,
  rows,
  axisWidth = DEFAULT_AXIS_WIDTH,
  axisTitle = DEFAULT_AXIS_TITLE,
  expandedIds,
  onToggleRow,
  compareLabel,
  compareTooltip,
  compareDisabled = false,
  compareChecked = false,
  onCompareChange,
  dataTestId,
}) => {
  const testId = (suffix: string) =>
    dataTestId ? `${dataTestId}-${suffix}` : undefined;

  return (
    <DDTCard data-testid={testId('card')}>
      <DrillDownTableToolbar
        title={title}
        unit={unit}
        compareLabel={compareLabel}
        compareTooltip={compareTooltip}
        compareDisabled={compareDisabled}
        compareChecked={compareChecked}
        onCompareChange={onCompareChange}
        dataTestId={dataTestId}
      />

      <DDTTable role="table" aria-label={title} data-testid={testId('table')}>
        <DrillDownTableHeader
          columnGroups={columnGroups}
          axisWidth={axisWidth}
          axisTitle={axisTitle}
          dataTestId={dataTestId}
        />

        <DDTBody role="rowgroup" data-testid={testId('body')}>
          {rows.map((row, rowIdx) => (
            <DrillDownTableRow
              key={row.id}
              row={row}
              rowIdx={rowIdx}
              columnGroups={columnGroups}
              axisWidth={axisWidth}
              expandedIds={expandedIds}
              onToggleRow={onToggleRow}
              dataTestId={dataTestId}
            />
          ))}
        </DDTBody>
      </DDTTable>
    </DDTCard>
  );
};
